set -e; export PATH="$HOME/.bun/bin:$PATH"; d=/tmp/tmp.MfVl4HTuh0; openclaw mcp show gbrain --json > "$d/mcp.json"; sdk="$HOME/.bun/install/global/node_modules/gbrain/node_modules/@modelcontextprotocol/sdk"; SDK="$sdk" RECEIPT="$d/mcp.json" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
const {Client}=await import(process.env.SDK+'/dist/esm/client/index.js');
const {StdioClientTransport}=await import(process.env.SDK+'/dist/esm/client/stdio.js');
const c=JSON.parse(readFileSync(process.env.RECEIPT));
const parsed=(r)=>{if(r.isError)throw Error(JSON.stringify(r.content));return r.structuredContent??JSON.parse(r.content.find(x=>x.type==='text').text)};
const client=new Client({name:'gbrain-install-verifier',version:'1.0.0'});
const transport=new StdioClientTransport({command:c.command,args:c.args,env:c.env,stderr:'inherit'});
try {
  await client.connect(transport);
  const {tools}=await client.listTools();
  for(const t of tools.filter(x=>['recall','forget'].includes(x.name)))console.log(t.name,JSON.stringify(t.inputSchema));
  const args={entity:'gbrain-install-check'};
  const call=async(name,args)=>parsed(await client.callTool({name,arguments:args,_meta:{hot_memory:'off'}}));
  const r=await call('recall',args);
  const hit=r.facts?.find(f=>f.fact?.includes('cobalt-marmot-7f43')&&f.source==='install-check');
  if(!hit)throw Error('Synthetic marker not returned: '+JSON.stringify(r));
  console.log('Verified MCP recall:',JSON.stringify(hit));
  const forget=await call('forget',{fact_id:String(hit.id),reason:'Completed the synthetic installation smoke test'});
  console.log('MCP forget:',JSON.stringify(forget));
  const after=await call('recall',args);
  if(!Array.isArray(after.facts)||after.facts.some(f=>String(f.id)===String(hit.id)))throw Error('Active recall still returns the marker, or recall did not return facts: '+JSON.stringify(after));
  console.log('Verified that the synthetic marker is absent from active recall.');
}finally{await client.close();}
